/**
 *  Códigos do domínio `versioning`. O código é contrato: renomear é mudança de contrato;
 *  acrescentar é permitido (só acréscimo, ROADMAP §1).
 */
export type VersioningErrorCode = 
/**  Bug: invariante quebrada sem código específico. */
"INTERNAL" | 
/**  A pasta do pack ainda não tem histórico de versões. */
"NOT_VERSIONED" | 
/**  A pasta do pack já tem histórico de versões. */
"ALREADY_VERSIONED" | 
/**  O histórico pertence a outro usuário do Windows (proteção da libgit2). */
"REPO_NOT_OWNED" | 
/**  Outro programa está mexendo no histórico agora (arquivo de trava do git). */
"REPO_LOCKED" | 
/**  O histórico está no meio de uma operação feita por fora (merge, rebase…). */
"REPO_BUSY" | 
/**  O histórico não está numa linha de versões (HEAD destacado). */
"DETACHED_HEAD" | 
/**  O histórico tem conflitos não resolvidos. */
"CONFLICTS" | 
/**  O texto não é uma versão no formato X.Y.Z. */
"INVALID_VERSION" | 
/**  A versão pedida não é maior que a última salva. */
"VERSION_NOT_GREATER" | 
/**  Já existe uma versão salva com esse número. */
"VERSION_EXISTS" | 
/**  Nada mudou desde a última versão salva. */
"NOTHING_CHANGED" | 
/**  A versão pedida não existe no histórico. */
"VERSION_NOT_FOUND" | 
/**  O ponto de segurança pedido não existe. */
"SAFETY_POINT_NOT_FOUND" | 
/**  A versão já foi publicada e não pode deixar de ser versão final. */
"VERSION_PUBLISHED" | 
/**  Um arquivo do pack está aberto em outro programa (o jogo, o antivírus…). */
"FILE_IN_USE" | 
/**  A restauração falhou e o pack não pôde voltar sozinho ao estado anterior. */
"ROLLBACK_FAILED" | 
/**  Falha da biblioteca git ao ler ou gravar o histórico. */
"GIT_FAILED";

/**  Por que um item está no pack. */
export type Why = 
/**  O usuário adicionou (pelo histórico). */
{ kind: "userAdded"; 
/**  Quando, se o histórico sabe. */
at: string | null } | 
/**  Sem histórico: nenhum outro item o exige, então foi escolha do usuário. */
{ kind: "noDependents" } | 
/**
 *  Exigido por outros itens: cada cadeia vai do item até um adicionado pelo usuário,
 *  da mais curta para a mais longa.
 */
{ kind: "requiredBy"; 
/**  As cadeias (cada uma começa no próprio item e termina no item do usuário). */
chains: ChainLink[][] } | 
/**  Nenhum item mantido o exige: pode ser removido. */
{ kind: "unused"; 
/**  Itens que só o usam como opcional, recomendado ou sugerido. */
optionalUsers: NodeRef[] };

/**  Resposta de [`Graph::why_in_pack`]. */
export type WhyReport = {
	/**  O item consultado. */
	item: NodeRef,
	/**  A resposta. */
	why: Why,
	/**  Os outros itens do ciclo de dependência do item (vazio fora de ciclo). */
	cycle: NodeRef[],
};

/* Tauri Specta runtime */
async function typedError<T, E>(result: Promise<T>): Promise<{ status: "ok"; data: T } | { status: "error"; error: E }> {
    try {
        return { status: "ok", data: await result };
    } catch (e) {
        if (e instanceof Error) throw e;
        return { status: "error", error: e as any };
    }
}

type EventEmit<T> = [T] extends [null] ? () => Promise<void> : (payload: T) => Promise<void>;

function makeEvent<T>(name: string, serialize?: (payload: T) => unknown, deserialize?: (payload: any) => T) {
    const mapEvent = (cb: __TAURI_EVENT.EventCallback<T>) => (event: __TAURI_EVENT.Event<any>) => cb({ ...event, payload: deserialize ? deserialize(event.payload) : event.payload });
    const mapPayload = (payload: T) => serialize ? serialize(payload) : payload;

    const base = {
        listen: (cb: __TAURI_EVENT.EventCallback<T>) => __TAURI_EVENT.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<T>) => __TAURI_EVENT.once(name, mapEvent(cb)),
        emit: ((payload: T) => __TAURI_EVENT.emit(name, mapPayload(payload)) as unknown) as EventEmit<T>
    };

    const fn = (target: import("@tauri-apps/api/webview").Webview | import("@tauri-apps/api/window").Window) => ({
        listen: (cb: __TAURI_EVENT.EventCallback<T>) => target.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<T>) => target.once(name, mapEvent(cb)),
        emit: ((payload: T) => target.emit(name, mapPayload(payload)) as unknown) as EventEmit<T>
    });

    return Object.assign(fn, base);
}

